// Define the enumeration representing possible data types
enum DataType {
    ScalarInt,
    ScalarFloat,
    ScalarComplex,
    ScalarBool,
    ScalarString,
    ArrayType,
    CompositeType,
    UnknownType,
}

// Implement the function to check if the given DataType is a scalar type
fn issctype(rep: DataType) -> bool {
    match rep {
        DataType::ScalarInt | 
        DataType::ScalarFloat | 
        DataType::ScalarComplex | 
        DataType::ScalarBool | 
        DataType::ScalarString => true,
        _ => false,
    }
}

// Example usage
fn main() {
    let scalar = DataType::ScalarInt;
    let non_scalar = DataType::ArrayType;

    println!("Is scalar: {}", issctype(scalar)); // Should print: Is scalar: true
    println!("Is scalar: {}", issctype(non_scalar)); // Should print: Is scalar: false
}